1	package consensus
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path/filepath"
8		"testing"
9	)
10	
11	// 本文件钉住“首次生成本地提议”的原子落盘回归保障。
12	//
13	// 场景：节点已有确认历史（第 1 轮确认，当前处于第 2 轮）。第 2 轮池内同时有
14	// 能够连续打包的交易（账户0 的 seq2/seq3 接在已确认序号 1 之后，账户1 的 seq1）
15	// 和因账户序号缺口而留在池中的交易（账户2 缺 seq1、只有 seq2）。本轮还没有本地
16	// 提议时，Propose 会选择交易、建立候选并把选中的交易置为等待投票，只有保存成功
17	// 才对外生效。当这次 Propose 因节点状态写入失败而返回错误时：不提供可用的提议
18	// 结果；Proposal 仍表示本轮尚无本地提议，Candidates 查询本轮仍按既有规则返回
19	// unknown-round；当前轮次与确认高度不前进，原有确认块的标识与交易顺序不变；
20	// 全部交易查询仍显示 queued，账户待处理列表、已确认序号与最早缺口不变，等待
21	// 说明仍是 waiting-pack，不出现 waiting-vote。磁盘状态文件逐字节不变、不残留
22	// 临时文件，重开节点看到同样的操作前状态。
23	//
24	// 失败不能留下候选引用造成的限制：保存恢复正常后，对原本可替换的排队交易提交
25	// 同发送者、同序号且费用严格更高的新交易，仍按原有规则成功替换，不能以
26	// tx-in-proposal 拒绝。再生成本地提议时以此时池中的有效交易为准，采用替换后的
27	// 交易标识，并继续遵守账户序号连续、费用排序和单块上限，不复用失败调用中准备
28	// 过的旧列表。成功生成后才恢复既有的冻结行为：提议中的交易禁止替换，后续提交
29	// 不改写这份提议。
30	//
31	// 没有可打包交易、首次尝试生成空块时遵守同一规则：失败不登记空块候选，保存
32	// 恢复后才可生成正常的空块提议。本组测试不新增公开入口，也不改变现有拒绝原因
33	// 与正常提议结果。
34	
35	// assertProposeRolledBack 断言首次 Propose 保存失败后节点完全处于操作前状态：
36	// 轮次 2、确认高度 1，确认块标识与交易顺序不变；本轮无本地提议、候选查询返回
37	// unknown-round；四笔池内交易全部 queued，账户已确认序号、待处理列表、最早
38	// 缺口与 waiting-pack 说明全部保持操作前结果，没有任何交易被置为等待投票。
39	func assertProposeRolledBack(t *testing.T, n *Node, confirmedBlock Block, keys []testKey, old, next, b1, gapTx *Transaction) {
40		t.Helper()
41		if n.CurrentRound() != 2 {
42			t.Fatalf("current round = %d, want 2 (failed propose must not advance the round)", n.CurrentRound())
43		}
44		if n.Height() != 1 {
45			t.Fatalf("confirmed height = %d, want 1", n.Height())
46		}
47		latest, ok := n.LatestBlock()
48		if !ok || latest.ID != confirmedBlock.ID || fmt.Sprint(latest.TxIDs) != fmt.Sprint(confirmedBlock.TxIDs) {
49			t.Fatalf("latest confirmed block changed: %+v ok=%v, want id=%s txs=%v",
50				latest, ok, confirmedBlock.ID, confirmedBlock.TxIDs)
51		}
52		blk, err := n.BlockAt(1)
53		if err != nil {
54			t.Fatal(err)
55		}
56		if blk.ID != confirmedBlock.ID || blk.Round != confirmedBlock.Round ||
57			fmt.Sprint(blk.TxIDs) != fmt.Sprint(confirmedBlock.TxIDs) {
58			t.Fatalf("confirmed history changed:\n got=%+v\nwant=%+v", blk, confirmedBlock)
59		}
60	
61		// 本轮尚无本地提议：Proposal 不可用，候选查询按既有规则返回 unknown-round。
62		if p, ok := n.Proposal(); ok {
63			t.Fatalf("round 2 must have no local proposal after the failed propose, got %+v", p)
64		}
65		if _, err := n.Candidates(2); reason(err) != ReasonUnknownRound {
66			t.Fatalf("candidates for round 2 must be %s, got %v", ReasonUnknownRound, err)
67		}
68		// 第 1 轮历史记录保留：已确认结束、唯一候选胜出。
69		rc1, err := n.Candidates(1)
70		if err != nil {
71			t.Fatal(err)
72		}
73		if !rc1.Ended || rc1.UnconfirmedEnd || !rc1.HasRecords {
74			t.Fatalf("round 1 history must stay a confirmed, recorded round: %+v", rc1)
75		}
76	
77		// 没有交易因失败的提议被锁住：全部仍是 queued，不带确认块关联。
78		for _, tx := range []*Transaction{old, next, b1, gapTx} {
79			info := n.mustTx(t, tx.ID())
80			if info.Status != StatusQueued {
81				t.Fatalf("tx %q status = %s, want queued after the failed propose", tx.Content, info.Status)
82			}
83			if info.BlockHeight != 0 || info.BlockID != "" || info.ReplacedBy != "" {
84				t.Fatalf("tx %q must not carry block/replace links: %+v", tx.Content, info)
85			}
86		}
87		// 账户待处理列表、已确认序号与缺口不变，等待说明仍是 waiting-pack。
88		assertAccountQueue(t, n, keys[0].pub, 1, map[string]string{
89			old.ID():  "waiting-pack",
90			next.ID(): "waiting-pack",
91		})
92		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{b1.ID(): "waiting-pack"})
93		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{gapTx.ID(): "waiting-pack"})
94		if a := n.Account(keys[0].pub); a.Gap != 0 {
95			t.Fatalf("account0 gap = %d, want 0", a.Gap)
96		}
97		if a := n.Account(keys[2].pub); a.Gap != 1 {
98			t.Fatalf("gap account gap = %d, want 1 (unchanged by the failed propose)", a.Gap)
99		}
100	}
101	
102	// TestProposeSaveFailureAtomic 覆盖首次生成本地提议保存失败的完整回归序列：
103	// 失败整体回滚（保存错误、结果为零值，轮次/高度/确认历史/交易状态/账户查询
104	// 全部照旧）-> 内存/磁盘/重开三处一致 -> 恢复后原可替换交易按正常规则替换、
105	// 重新生成的提议采用替换后的交易并遵守全部打包规则 -> 成功生成后冻结行为恢复。
106	func TestProposeSaveFailureAtomic(t *testing.T) {
107		keys := genKeys(t, 4)
108		n, dir := newTestNode(t, keys, 3)
109	
110		// 第 1 轮：确认账户0 的 seq1，留下一块确认历史，进入第 2 轮。
111		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
112		if _, err := n.Submit(a1); err != nil {
113			t.Fatal(err)
114		}
115		p1 := assertProposalOrder(t, n, []string{a1.ID()})
116		confirmByVotes(t, n, keys, p1.BlockID)
117		confirmedBlock, err := n.BlockAt(1)
118		if err != nil {
119			t.Fatal(err)
120		}
121		if n.CurrentRound() != 2 || n.Height() != 1 {
122			t.Fatalf("setup: round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
123		}
124	
125		// 第 2 轮池内布局：账户0 的 seq2/seq3 接已确认序号 1 连续可打包，
126		// 账户1 的 seq1 可打包，账户2 缺 seq1、seq2 费用再高也只能留在池中。
127		old := NewTransaction(keys[0].priv, 2, []byte("old"), 20, 100)
128		next := NewTransaction(keys[0].priv, 3, []byte("next"), 30, 100)
129		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
130		gapTx := NewTransaction(keys[2].priv, 2, []byte("gap"), 99, 100)
131		for _, tx := range []*Transaction{old, next, b1, gapTx} {
132			if _, err := n.Submit(tx); err != nil {
133				t.Fatalf("setup submit %q: %v", tx.Content, err)
134			}
135		}
136		// 失败调用本应准备的列表：费用排序 b1(50)、old(20)，old 选入后 next(30)
137		// 才具备条件，恰好取满单块上限 3 笔；gapTx 受序号缺口阻挡不得入选。
138		failedList := []string{b1.ID(), old.ID(), next.ID()}
139		failedBlockID := BlockID(2, 2, confirmedBlock.ID, failedList)
140		assertProposeRolledBack(t, n, confirmedBlock, keys, old, next, b1, gapTx)
141	
142		// 快照首次提议前的磁盘文件：失败的保存不得改写它，也不得残留临时文件。
143		before, err := os.ReadFile(filepath.Join(dir, stateFileName))
144		if err != nil {
145			t.Fatal(err)
146		}
147	
148		// 首次 Propose 在此刻保存节点状态失败：必须返回保存错误，且不能同时
149		// 给出可用的提议结果。
150		n.injectSaveErr = errors.New("disk full (simulated)")
151		view, err := n.Propose()
152		n.injectSaveErr = nil
153		if err == nil {
154			t.Fatal("first propose must return the save error when saving node state fails")
155		}
156		if reason(err) != "" {
157			t.Fatalf("save failure must surface as an infrastructure error, not a rejection %q: %v", reason(err), err)
158		}
159		if view.Round != 0 || view.BlockID != "" || len(view.TxIDs) != 0 || view.Empty {
160			t.Fatalf("propose result must be the zero value on save failure, got %+v", view)
161		}
162	
163		// 内存：轮次、高度、确认历史、交易状态与账户查询全部保持操作前结果，
164		// 没有一份已经生效却没有保存的提议，也没有交易因此被锁住。
165		assertProposeRolledBack(t, n, confirmedBlock, keys, old, next, b1, gapTx)
166	
167		// 磁盘：状态文件逐字节不变，目录中仅有 state.json。
168		assertStateFileUnchanged(t, dir, before)
169	
170		// 重开节点：保存记录中没有本次提议造成的任何变化——仍没有本轮提议，
171		// 原交易继续排队，确认历史保持原样。
172		reopened, err := Open(dir)
173		if err != nil {
174			t.Fatal(err)
175		}
176		assertProposeRolledBack(t, reopened, confirmedBlock, keys, old, next, b1, gapTx)
177	
178		// 保存恢复正常后，对原本可替换的排队交易提交同发送者、同序号且费用
179		// 严格更高的新交易：必须按一次正常替换成功处理，不能以 tx-in-proposal
180		// 拒绝（失败的提议没有留下候选引用造成的限制）。
181		newTx := NewTransaction(keys[0].priv, 2, []byte("new"), 60, 100)
182		if newTx.ID() == old.ID() || newTx.Fee <= old.Fee {
183			t.Fatal("setup: replacement must differ from old tx with a strictly higher fee")
184		}
185		res, err := reopened.Submit(newTx)
186		if err != nil {
187			t.Fatalf("replacement after recovery must succeed as a normal replacement: %v", err)
188		}
189		if res.TxID != newTx.ID() || res.ReplacedID != old.ID() || res.EvictedID != "" {
190			t.Fatalf("replacement result = %+v, want {TxID:%s ReplacedID:%s EvictedID:\"\"}",
191				res, newTx.ID(), old.ID())
192		}
193		oldInfo := reopened.mustTx(t, old.ID())
194		if oldInfo.Status != StatusReplaced || oldInfo.ReplacedBy != newTx.ID() {
195			t.Fatalf("old tx = {status:%s replacedBy:%s}, want replaced by %s",
196				oldInfo.Status, oldInfo.ReplacedBy, newTx.ID())
197		}
198	
199		// 再生成本地提议：以此时池中的有效交易为准，采用替换后的交易标识，
200		// 继续遵守账户序号连续、费用排序和单块上限——newTx(60)、b1(50)、next(30)，
201		// 不复用失败调用中准备过的旧列表（含 old、顺序不同）。
202		wantList := []string{newTx.ID(), b1.ID(), next.ID()}
203		view, err = reopened.Propose()
204		if err != nil {
205			t.Fatalf("propose after recovery: %v", err)
206		}
207		if view.Round != 2 || view.Empty || fmt.Sprint(view.TxIDs) != fmt.Sprint(wantList) {
208			t.Fatalf("regenerated proposal = %+v, want round 2 txs %v", view, wantList)
209		}
210		if wantID := BlockID(2, 2, confirmedBlock.ID, wantList); view.BlockID != wantID {
211			t.Fatalf("regenerated block id = %s, want %s", view.BlockID, wantID)
212		}
213		if view.BlockID == failedBlockID {
214			t.Fatal("regenerated proposal must not reuse the failed attempt's tx list")
215		}
216		// 提议生成后：选中的交易等待投票，缺口交易仍等待打包；已确认序号不推进。
217		assertAccountQueue(t, reopened, keys[0].pub, 1, map[string]string{
218			newTx.ID(): "waiting-vote",
219			next.ID():  "waiting-vote",
220		})
221		assertAccountQueue(t, reopened, keys[1].pub, 0, map[string]string{b1.ID(): "waiting-vote"})
222		assertAccountQueue(t, reopened, keys[2].pub, 0, map[string]string{gapTx.ID(): "waiting-pack"})
223		if info := reopened.mustTx(t, gapTx.ID()); info.Status != StatusQueued {
224			t.Fatalf("gap tx status = %s, want queued (sequence gap still blocks packing)", info.Status)
225		}
226	
227		// 成功生成后才恢复既有的冻结行为：提议中的交易禁止替换。
228		hiB := NewTransaction(keys[1].priv, 1, []byte("b1-hi"), 70, 100)
229		if _, err := reopened.Submit(hiB); reason(err) != ReasonProposalLocked {
230			t.Fatalf("replacing a proposed tx must be rejected with %s, got %v", ReasonProposalLocked, err)
231		}
232		// 后续新提交不改写这份提议：重复 Propose 与 Proposal 都返回同一提议。
233		extra := NewTransaction(keys[3].priv, 1, []byte("extra"), 80, 100)
234		if _, err := reopened.Submit(extra); err != nil {
235			t.Fatal(err)
236		}
237		again, err := reopened.Propose()
238		if err != nil {
239			t.Fatal(err)
240		}
241		if again.BlockID != view.BlockID || fmt.Sprint(again.TxIDs) != fmt.Sprint(wantList) {
242			t.Fatalf("proposal must stay frozen after new submissions: %+v, want %+v", again, view)
243		}
244		p, ok := reopened.Proposal()
245		if !ok || p.BlockID != view.BlockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(wantList) {
246			t.Fatalf("local proposal view changed after new submissions: %+v ok=%v", p, ok)
247		}
248		if info := reopened.mustTx(t, extra.ID()); info.Status != StatusQueued {
249			t.Fatalf("late submission status = %s, want queued (not packed into the frozen proposal)", info.Status)
250		}
251	
252		// 提议结果随再次落盘持久化：再次重开看到完全一致的状态。
253		durable, err := Open(dir)
254		if err != nil {
255			t.Fatal(err)
256		}
257		dp, ok := durable.Proposal()
258		if !ok || dp.BlockID != view.BlockID || fmt.Sprint(dp.TxIDs) != fmt.Sprint(wantList) {
259			t.Fatalf("durable proposal = %+v ok=%v, want %+v", dp, ok, view)
260		}
261		if info := durable.mustTx(t, old.ID()); info.Status != StatusReplaced || info.ReplacedBy != newTx.ID() {
262			t.Fatalf("durable old tx wrong: %+v", info)
263		}
264		assertAccountQueue(t, durable, keys[0].pub, 1, map[string]string{
265			newTx.ID(): "waiting-vote",
266			next.ID():  "waiting-vote",
267		})
268		assertAccountQueue(t, durable, keys[2].pub, 0, map[string]string{gapTx.ID(): "waiting-pack"})
269	}
270	
271	// assertEmptyProposeRolledBack 断言空块提议保存失败后节点完全处于操作前状态：
272	// 轮次 1、高度 0；本轮无本地提议、候选查询返回 unknown-round；因序号缺口
273	// 留在池中的交易仍 queued，账户缺口与 waiting-pack 说明不变。
274	func assertEmptyProposeRolledBack(t *testing.T, n *Node, key testKey, gapTx *Transaction) {
275		t.Helper()
276		if n.CurrentRound() != 1 {
277			t.Fatalf("current round = %d, want 1 (failed empty propose must not advance the round)", n.CurrentRound())
278		}
279		if n.Height() != 0 {
280			t.Fatalf("confirmed height = %d, want 0", n.Height())
281		}
282		if _, ok := n.LatestBlock(); ok {
283			t.Fatal("latest confirmed block must not exist")
284		}
285		if p, ok := n.Proposal(); ok {
286			t.Fatalf("round 1 must have no local proposal after the failed propose, got %+v", p)
287		}
288		if _, err := n.Candidates(1); reason(err) != ReasonUnknownRound {
289			t.Fatalf("candidates for round 1 must be %s, got %v", ReasonUnknownRound, err)
290		}
291		info := n.mustTx(t, gapTx.ID())
292		if info.Status != StatusQueued {
293			t.Fatalf("gap tx status = %s, want queued after the failed empty propose", info.Status)
294		}
295		assertAccountQueue(t, n, key.pub, 0, map[string]string{gapTx.ID(): "waiting-pack"})
296		if a := n.Account(key.pub); a.Gap != 1 {
297			t.Fatalf("gap account gap = %d, want 1 (unchanged by the failed empty propose)", a.Gap)
298		}
299	}
300	
301	// TestProposeSaveFailureAtomicEmptyBlock 把“首次尝试生成空块”纳入同一项保障：
302	// 没有可打包交易时（池中仅有因序号缺口等待的交易），Propose 保存失败不登记
303	// 空块候选——内存/磁盘/重开三处都与操作前一致；保存恢复后才可生成正常的
304	// 空块提议，且生成后即冻结，后续提交不改写这份空块提议。
305	func TestProposeSaveFailureAtomicEmptyBlock(t *testing.T) {
306		keys := genKeys(t, 4)
307		n, dir := newTestNode(t, keys, 3)
308	
309		// 池中只有因序号缺口等待的交易：没有任何可打包交易，首次提议应为空块。
310		gapTx := NewTransaction(keys[0].priv, 2, []byte("gap"), 99, 100)
311		if _, err := n.Submit(gapTx); err != nil {
312			t.Fatal(err)
313		}
314		assertEmptyProposeRolledBack(t, n, keys[0], gapTx)
315	
316		before, err := os.ReadFile(filepath.Join(dir, stateFileName))
317		if err != nil {
318			t.Fatal(err)
319		}
320	
321		// 首次空块提议在此刻保存失败：返回保存错误，结果为零值。
322		n.injectSaveErr = errors.New("disk full (simulated)")
323		view, err := n.Propose()
324		n.injectSaveErr = nil
325		if err == nil {
326			t.Fatal("first empty-block propose must return the save error when saving node state fails")
327		}
328		if reason(err) != "" {
329			t.Fatalf("save failure must surface as an infrastructure error, not a rejection %q: %v", reason(err), err)
330		}
331		if view.Round != 0 || view.BlockID != "" || len(view.TxIDs) != 0 || view.Empty {
332			t.Fatalf("propose result must be the zero value on save failure, got %+v", view)
333		}
334	
335		// 内存：不登记空块候选，节点完全处于操作前状态。
336		assertEmptyProposeRolledBack(t, n, keys[0], gapTx)
337	
338		// 磁盘：状态文件逐字节不变，目录中仅有 state.json。
339		assertStateFileUnchanged(t, dir, before)
340	
341		// 重开节点：仍没有本轮提议，缺口交易继续排队。
342		reopened, err := Open(dir)
343		if err != nil {
344			t.Fatal(err)
345		}
346		assertEmptyProposeRolledBack(t, reopened, keys[0], gapTx)
347	
348		// 保存恢复正常后：可生成正常的空块提议，标识按公开规则由轮次、高度、
349		// 前块标识与空交易列表确定。
350		view, err = reopened.Propose()
351		if err != nil {
352			t.Fatalf("empty-block propose after recovery: %v", err)
353		}
354		if view.Round != 1 || !view.Empty || len(view.TxIDs) != 0 {
355			t.Fatalf("regenerated proposal = %+v, want an empty round-1 block", view)
356		}
357		if wantID := BlockID(1, 1, "", []string{}); view.BlockID != wantID {
358			t.Fatalf("empty block id = %s, want %s", view.BlockID, wantID)
359		}
360		// 空块候选已登记：本地候选 pending、0 票，缺口交易仍等待打包。
361		rc, err := reopened.Candidates(1)
362		if err != nil {
363			t.Fatal(err)
364		}
365		if rc.Ended || !rc.HasRecords || len(rc.Candidates) != 1 {
366			t.Fatalf("round 1 must have exactly one recorded pending candidate: %+v", rc)
367		}
368		c := rc.Candidates[0]
369		if !c.Local || c.Result != CandidatePending || c.BlockID != view.BlockID || len(c.TxIDs) != 0 || len(c.Voters) != 0 {
370			t.Fatalf("empty local candidate wrong: %+v", c)
371		}
372		assertAccountQueue(t, reopened, keys[0].pub, 0, map[string]string{gapTx.ID(): "waiting-pack"})
373	
374		// 空块提议生成后同样冻结：补上缺口序号使原交易变为可打包，提议也不改写。
375		fill := NewTransaction(keys[0].priv, 1, []byte("fill"), 1, 100)
376		if _, err := reopened.Submit(fill); err != nil {
377			t.Fatal(err)
378		}
379		again, err := reopened.Propose()
380		if err != nil {
381			t.Fatal(err)
382		}
383		if again.BlockID != view.BlockID || !again.Empty {
384			t.Fatalf("empty proposal must stay frozen after new submissions: %+v, want %+v", again, view)
385		}
386		if info := reopened.mustTx(t, fill.ID()); info.Status != StatusQueued {
387			t.Fatalf("late submission status = %s, want queued (not packed into the frozen empty proposal)", info.Status)
388		}
389	
390		// 空块提议随再次落盘持久化：再次重开看到完全一致的状态。
391		durable, err := Open(dir)
392		if err != nil {
393			t.Fatal(err)
394		}
395		dp, ok := durable.Proposal()
396		if !ok || dp.BlockID != view.BlockID || !dp.Empty {
397			t.Fatalf("durable empty proposal = %+v ok=%v, want %+v", dp, ok, view)
398		}
399	}
