186		assertReplaceRolledBack(t, n, keys[0], old, later, newTx.ID())
187	
188		// 磁盘：状态文件逐字节不变，目录中仅有 state.json。
189		assertStateFileUnchanged(t, dir, before)
190	
191		// 重开节点：保存记录中没有本次替换造成的任何变化——不能出现当前查询
192		// 恢复了旧交易、再次打开却看到新交易已替换成功的差异。
193		reopened, err := Open(dir)
194		if err != nil {
195			t.Fatal(err)
196		}
197		assertReplaceRolledBack(t, reopened, keys[0], old, later, newTx.ID())
198	
199		// 保存恢复正常后，再提交刚才失败的同一笔新交易：必须按一次正常替换成功
200		// 处理，不能因失败尝试残留记录而被认作重复交易。
201		res, err = reopened.Submit(newTx)
202		if err != nil {
203			t.Fatalf("resubmit after recovery must succeed as a normal replacement: %v", err)
204		}
205		if res.TxID != newTx.ID() || res.ReplacedID != old.ID() || res.EvictedID != "" {
206			t.Fatalf("replacement result = %+v, want {TxID:%s ReplacedID:%s EvictedID:\"\"}",
207				res, newTx.ID(), old.ID())
208		}
209		assertReplaceApplied(t, reopened, keys[0], old, newTx, later)
210	
211		// 替换结果随再次落盘持久化：再次重开看到完全一致的状态。
212		durable, err := Open(dir)
213		if err != nil {
214			t.Fatal(err)
215		}
216		assertReplaceApplied(t, durable, keys[0], old, newTx, later)
217	}
218	
219	// assertFullPoolRolledBack 断言（满池场景）保存失败后节点完全处于操作前状态：
220	// 旧交易仍排队、新交易无记录；池内其他账户的待处理交易保持排队，此前被挤出的
221	// 交易保留 dropped 记录与淘汰关联（原因与发生轮次），没有为了给新交易腾位置
222	// 而挤出任何交易。
223	func assertFullPoolRolledBack(t *testing.T, n *Node, keys []testKey, old, otherC, d, dropped *Transaction, newID string) {
224		t.Helper()
225		assertOldTxQueued(t, n, old)
226		assertNewTxUnknown(t, n, newID)
227	
228		// 其他账户的排队交易原样保留。
229		for _, tx := range []*Transaction{otherC, d} {
230			info := n.mustTx(t, tx.ID())
231			if info.Status != StatusQueued {
232				t.Fatalf("unrelated tx %q status = %s, want queued after the failed replacement", tx.Content, info.Status)
233			}
234			assertTxMatches(t, info.Tx, tx)
235		}
236		// 既有的淘汰记录与关联保持原样：原因 pool-capacity、发生轮次 1，
237		// 不带确认块或替换关联。
238		dropInfo := n.mustTx(t, dropped.ID())
239		if dropInfo.Status != StatusDropped || dropInfo.DropReason != DropReasonPoolCapacity || dropInfo.DropRound != 1 {
240			t.Fatalf("dropped record changed: %+v", dropInfo)
241		}
242		if dropInfo.BlockHeight != 0 || dropInfo.BlockID != "" || dropInfo.ReplacedBy != "" {
243			t.Fatalf("dropped tx must not carry block/replace links: %+v", dropInfo)
244		}
245		assertTxMatches(t, dropInfo.Tx, dropped)
246	
247		// 各账户查询：已确认序号均为 0；旧交易账户只有旧交易排队，被挤出账户
248		// 没有待处理交易，其余账户各留自己的一笔。
249		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{old.ID(): "waiting-pack"})
250		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{})
251		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{otherC.ID(): "waiting-pack"})
252		assertAccountQueue(t, n, keys[3].pub, 0, map[string]string{d.ID(): "waiting-pack"})
253	}
254	
255	// assertFullPoolReplaced 断言（满池场景）保存恢复后同一笔新交易替换成功后的
256	// 状态：旧交易被替换并指向新交易，新交易排队；替换不新增占位、不淘汰其他
257	// 交易——其他账户的排队交易与既有淘汰记录全部保持原样，已确认序号不推进。
258	func assertFullPoolReplaced(t *testing.T, n *Node, keys []testKey, old, newTx, otherC, d, dropped *Transaction) {
259		t.Helper()
260		oldInfo := n.mustTx(t, old.ID())
261		if oldInfo.Status != StatusReplaced || oldInfo.ReplacedBy != newTx.ID() {
262			t.Fatalf("old tx = {status:%s replacedBy:%s}, want replaced by %s",
263				oldInfo.Status, oldInfo.ReplacedBy, newTx.ID())
264		}
265		newInfo := n.mustTx(t, newTx.ID())
266		if newInfo.Status != StatusQueued {
267			t.Fatalf("new tx status = %s, want queued", newInfo.Status)
268		}
269		assertTxMatches(t, newInfo.Tx, newTx)
270	
271		// 池满也不影响其他账户：排队交易与淘汰记录原样。
272		for _, tx := range []*Transaction{otherC, d} {
273			if info := n.mustTx(t, tx.ID()); info.Status != StatusQueued {
274				t.Fatalf("unrelated tx %q status = %s, want queued", tx.Content, info.Status)
275			}
276		}
277		dropInfo := n.mustTx(t, dropped.ID())
278		if dropInfo.Status != StatusDropped || dropInfo.DropReason != DropReasonPoolCapacity || dropInfo.DropRound != 1 {
279			t.Fatalf("dropped record changed by the replacement: %+v", dropInfo)
280		}
281		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{newTx.ID(): "waiting-pack"})
282		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{})
283		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{otherC.ID(): "waiting-pack"})
284		assertAccountQueue(t, n, keys[3].pub, 0, map[string]string{d.ID(): "waiting-pack"})
285	}
286	
287	// TestReplaceSaveFailureAtomicFullPool 把池容量用满的情况纳入同一项保障：
288	// 合法加费替换不新增占位，保存失败不能为了给新交易腾位置而挤出其他交易；
289	// 恢复后同一笔新交易替换成功，结果不带被挤出标识，其他账户不受影响。
290	func TestReplaceSaveFailureAtomicFullPool(t *testing.T) {
291		keys := genKeys(t, 4)
292		n, dir := newTestNodeCap(t, keys, 10, 3)
293	
294		// 池容量 3：旧交易（账户0，费用 4）与另外两账户的交易把池占满。
295		old := NewTransaction(keys[0].priv, 1, []byte("old"), 4, 100)
296		otherB := NewTransaction(keys[1].priv, 1, []byte("other-b"), 2, 100)
297		otherC := NewTransaction(keys[2].priv, 1, []byte("other-c"), 3, 100)
298		for _, tx := range []*Transaction{old, otherB, otherC} {
299			if _, err := n.Submit(tx); err != nil {
300				t.Fatalf("setup submit %q: %v", tx.Content, err)
301			}
302		}
303		// 账户3 的高费交易挤出费用最低的 otherB，留下一条既有淘汰记录；
304		// 池仍为满：old(4)、otherC(3)、d(9)。
305		d := NewTransaction(keys[3].priv, 1, []byte("d"), 9, 100)
306		res, err := n.Submit(d)
307		if err != nil || res.EvictedID != otherB.ID() {
308			t.Fatalf("setup eviction: %+v %v", res, err)
309		}
310	
311		// 满池下的合法加费替换：同发送者同序号、费用严格更高，不新增占位，
312		// 也不应淘汰任何交易。
313		newTx := NewTransaction(keys[0].priv, 1, []byte("new"), 10, 100)
314		assertFullPoolRolledBack(t, n, keys, old, otherC, d, otherB, newTx.ID())
315	
316		before, err := os.ReadFile(filepath.Join(dir, stateFileName))
317		if err != nil {
318			t.Fatal(err)
319		}
320	
321		// 满池时的合法替换在此刻保存失败：返回保存错误且结果为空。
322		n.injectSaveErr = errors.New("disk full (simulated)")
323		res, err = n.Submit(newTx)
324		n.injectSaveErr = nil
325		if err == nil {
326			t.Fatal("replacement on a full pool must return the save error when saving node state fails")
327		}
328		if reason(err) != "" {
329			t.Fatalf("save failure must surface as an infrastructure error, not a submit rejection %q: %v", reason(err), err)
330		}
331		if res != nil {
332			t.Fatalf("submit result must be nil on save failure, got %+v", res)
333		}
334	
335		// 内存：旧交易仍在，新交易无记录；没有为了给新交易腾位置而挤出其他
336		// 交易——其他账户的待处理记录与淘汰关联全部保持原样。
337		assertFullPoolRolledBack(t, n, keys, old, otherC, d, otherB, newTx.ID())
338	
339		// 磁盘：状态文件逐字节不变，目录中仅有 state.json。
340		assertStateFileUnchanged(t, dir, before)
341	
342		// 重开节点：与当前查询完全一致的操作前状态。
343		reopened, err := Open(dir)
344		if err != nil {
345			t.Fatal(err)
346		}
347		assertFullPoolRolledBack(t, reopened, keys, old, otherC, d, otherB, newTx.ID())
348	
349		// 保存恢复正常后，再提交刚才失败的同一笔新交易：按一次正常替换成功
350		// 处理——结果关联被替换的旧标识，不带被挤出标识（满池也不淘汰）。
351		res, err = reopened.Submit(newTx)
352		if err != nil {
353			t.Fatalf("resubmit on full pool after recovery must succeed as a normal replacement: %v", err)
354		}
355		if res.TxID != newTx.ID() || res.ReplacedID != old.ID() || res.EvictedID != "" {
356			t.Fatalf("full-pool replacement result = %+v, want {TxID:%s ReplacedID:%s EvictedID:\"\"}",
357				res, newTx.ID(), old.ID())
358		}
359		assertFullPoolReplaced(t, reopened, keys, old, newTx, otherC, d, otherB)
360	
361		// 替换结果随再次落盘持久化：再次重开看到完全一致的状态。
362		durable, err := Open(dir)
363		if err != nil {
364			t.Fatal(err)
365		}
366		assertFullPoolReplaced(t, durable, keys, old, newTx, otherC, d, otherB)
367	}
