356		acct = n.Account(keys[0].pub)
357		if acct.Pending[0].Status != StatusQueued || acct.Pending[0].Note != "waiting-pack" {
358			t.Fatalf("returned tx should be queued/waiting-pack: %+v", acct.Pending[0])
359		}
360		if _, ok := n.Proposal(); ok {
361			t.Fatal("proposal should be cleared after EndRound")
362		}
363		if n.Height() != 0 {
364			t.Fatal("ended round must leave no confirmed block")
365		}
