580		if err != nil || !res.Confirmed {
581			t.Fatalf("alt should confirm after reopen: %+v %v", res, err)
582		}
583		// 历史结果保留，新轮无候选记录。
584		rc, _ = n2.Candidates(1)
585		for _, c := range rc.Candidates {
586			want := CandidateWon
587			if c.BlockID != altID {
