662	// 版本 1 的历史轮次：确认轮与主动结束轮都没有候选详情，确认块本身不变。
663	func TestOpenV1HistoryRounds(t *testing.T) {
664		keys := genKeys(t, 4)
665		dir := t.TempDir()
666		vals := make([][]byte, len(keys))
